using System.Net.Http.Json;
using System.Text.Json;
using ModelContextProtocol.Server;

[McpServerToolType]
public static class WeatherTools
{
    [McpServerTool(Name = "get_weather",
        Description = "Gets current weather for a location given latitude and longitude.")]
    public static async Task<string> GetWeather(
        IHttpClientFactory httpClientFactory,
        [McpServerToolParameter(Description = "Latitude of the location")] double latitude,
        [McpServerToolParameter(Description = "Longitude of the location")] double longitude)
    {
        var client = httpClientFactory.CreateClient("WeatherApi");

        var url = $"/v1/forecast?latitude={latitude}&longitude={longitude}&current_weather=true";
        var response = await client.GetFromJsonAsync<JsonElement>(url);

        var weather = response.GetProperty("current_weather");
        return $"Temperature: {weather.GetProperty("temperature")}°C, " +
               $"Wind: {weather.GetProperty("windspeed")} km/h";
    }

    [McpServerTool(Name = "get_forecast",
        Description = "Gets a 7-day weather forecast for a location.")]
    public static async Task<string> GetForecast(
        IHttpClientFactory httpClientFactory,
        [McpServerToolParameter(Description = "Latitude of the location")] double latitude,
        [McpServerToolParameter(Description = "Longitude of the location")] double longitude)
    {
        var client = httpClientFactory.CreateClient("WeatherApi");

        var url = $"/v1/forecast?latitude={latitude}&longitude={longitude}" +
                  "&daily=temperature_2m_max,temperature_2m_min&timezone=auto";
        var response = await client.GetFromJsonAsync<JsonElement>(url);

        var daily = response.GetProperty("daily");
        var dates = daily.GetProperty("time").EnumerateArray().ToList();
        var maxTemps = daily.GetProperty("temperature_2m_max").EnumerateArray().ToList();
        var minTemps = daily.GetProperty("temperature_2m_min").EnumerateArray().ToList();

        var lines = dates.Select((d, i) =>
            $"{d.GetString()}: {minTemps[i]}–{maxTemps[i]}°C");

        return string.Join("\n", lines);
    }
}

